"""
aetherion_cli/commands/diff.py
Diff and worktree change inspection command.
"""
from __future__ import annotations

import click
from rich.syntax import Syntax

from ..api.client import ApiClient
from ..output.formatters import print_error_and_exit, stdout_console


@click.command("diff")
@click.argument("task_id")
@click.option("--json", "as_json", is_flag=True, help="Output raw diff string as JSON.")
def diff_cmd(task_id: str, as_json: bool) -> None:
    """Show git / worktree code changes generated by a task."""
    client = ApiClient()
    try:
        diff_text = client.get_diff(task_id)
        if as_json:
            stdout_console.print_json(data={"task_id": task_id, "diff": diff_text})
        else:
            if not diff_text or not diff_text.strip():
                stdout_console.print("[dim]No file modifications found for this task.[/dim]")
            else:
                syntax = Syntax(diff_text, "diff", theme="monokai", line_numbers=True)
                stdout_console.print(syntax)
    except Exception as e:
        print_error_and_exit(f"Failed to fetch diff: {e}", as_json=as_json)
